// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 amount_, uint256 rate_, uint256 duration_) internal {
        uint256 reported;
        try c.interestFor(amount_, rate_, duration_) returns (uint256 __r) { reported = __r; } catch { return; }
        uint256 DECIMALS = 1000000000000000000;
        uint256 interestComponent = (rate_ * duration_) / 365 days;
        uint256 expected = (amount_ * interestComponent) / DECIMALS;
        assertTrue(reported == expected);
    }

    function testFuzz_run(uint256 amount_, uint256 rate_, uint256 duration_) public {
        _run(amount_, rate_, duration_);
    }

    receive() external payable {}
}
